{
  "intent": "change_explanation",
  "metrics": ["profit"],
  "dimensions": ["category", "fiscal_period"],
  "time_range": "2023-01-01 to 2024-12-31",
  "comparison_period": null,
  "hypotheses": [
    "Profit drop began at a specific point in late 2024",
    "Specific categories contributed disproportionately to the profit fall",
    "The profit shift is structural rather than seasonal"
  ],
  "analysis_plan": [
    {
      "analysis": "changepoint",
      "params": {
        "measure": "profit"
      },
      "purpose": "Find when profit started to change level across the calendar in 2024"
    },
    {
      "analysis": "growth_decomposition",
      "params": {
        "measure": "profit",
        "dimension": "category",
        "period": "2024-10",
        "baseline": "2024-07"
      },
      "purpose": "Identify which categories drove the change in profit between periods"
    },
    {
      "analysis": "seasonality",
      "params": {
        "measure": "profit",
        "grain": "month"
      },
      "purpose": "Examine monthly seasonality to determine if the late 2024 drop is seasonal or structural"
    }
  ],
  "research_required": false,
  "insufficient_data": false,
  "stop_conditions": [
    "If changepoint detects no significant level shift in late 2024, evaluate trend directly",
    "If category decomposition fails due to missing period format, use group compare across periods"
  ]
}

